<script setup>import { useRoute } from 'vue-router'import { computed, onMounted, ref, nextTick } from 'vue'const route = useRoute()const dynamicTitle = ref('')const map = {  collections: 'Колекції',  products: 'Товари',  pages: 'Сторінки',  blogs: 'Блог',  about: 'Про нас',  contact: 'Контакти'}const findTitle = () => {  const h1 = document.querySelector('h1')  if (h1) {    dynamicTitle.value = h1.textContent.trim()    return true  }  return false}onMounted(async () => {  await nextTick()  if (findTitle()) return  let attempts = 0  const interval = setInterval(() => {    if (findTitle() || attempts++ > 10) clearInterval(interval)  }, 200)})const crumbs = computed(() => {  const parts = route.path.split('/').filter(Boolean)  const trail = []  parts.forEach((part, index) => {    const path = '/' + parts.slice(0, index + 1).join('/')    const isLast = index === parts.length - 1    const label =        isLast && dynamicTitle.value            ? dynamicTitle.value            : map[part] || decodeURIComponent(part).replace(/-/g, ' ')    trail.push({ label, path })  })  return trail})</script><template>  <nav class="breadcrumb" aria-label="breadcrumb">    <ul>      <li>        <NuxtLink to="/">Головна</NuxtLink>      </li>      <li v-for="(crumb, i) in crumbs" :key="i">        <template v-if="i < crumbs.length - 1">          <NuxtLink :to="crumb.path">{{ crumb.label }}</NuxtLink>        </template>        <template v-else>          <span class="active">{{ crumb.label }}</span>        </template>      </li>    </ul>  </nav></template>